28	static const uint32_t IN_TENSOR_COUNT_THREE = 3;
29	static const uint32_t IN_TENSOR_COUNT_FOUR = 4;
30	static const uint32_t IN_TENSOR_COUNT_FIVE = 5;
31	static const uint32_t IN_TENSOR_COUNT_SIX = 6;
32	static const uint32_t OUT_TENSOR_COUNT_TWO = 2;
33	static const uint32_t OUT_TENSOR_COUNT_THREE = 3;
34	static const uint32_t IN_TENSOR_SCALE_NORMNORM = 3;
35	static const uint32_t IN_TENSOR_OFFSET_NORMNORM = 4;
36	static const uint32_t IN_TENSOR_SCALE_POSTNORM = 4;
37	static const uint32_t IN_TENSOR_OFFSET_POSTNORM = 5;
38	static const uint32_t IN_TENSOR_GAMMA_PRE_POSTNORM = 2;
39	static const uint32_t X_TENSOR = 0;
40	static const uint32_t RESIDUAL_IN_TENSOR = 1;
41	static const uint32_t GAMMA_IN_TENSOR = 2;
42	static const uint32_t BETA_IN_TENSOR = 3;
43	static const uint32_t GAMMA_IN_TENSOR_NORM = 1;
44	static const uint32_t BETA_IN_TENSOR_NORM = 2;
45	static const uint32_t DIM_0 = 0;
46	static const uint32_t DIM_2 = 2;
47	static const uint32_t SIZE_1 = 1;
48	static const uint32_t ALIGNMENT = 32;
49	static const uint32_t QUANT_TENSOR_COUNT = 2;
50	static const float THRESHOLD = 2e-38; // The non-negative minimum value of float type is 1.17549e-038.
51	static const uint32_t DYNAMIC_QUANT_MAX_TENSOR_LENGTH = 12288;
52	
53	Status NormParamCheck(infer::LayerNormParam::NormParam normParam)
54	{
55	    if (normParam.quantType != infer::QUANT_UNQUANT && normParam.quantType != infer::QUANT_INT8) {
56	        ATB_LOG(ERROR) << "quantType is not supported, only support QUANT_UNQUANT/QUANT_INT8";
57	        return ERROR_INVALID_PARAM;
58	    }
59	    if (std::fabs(normParam.epsilon) < THRESHOLD) {
60	        ATB_LOG(ERROR) << "Invalid epsilon, it's recommended to init a nonzero value for eps.";
61	        return ERROR_INVALID_PARAM;
62	    }
63	    if (normParam.dynamicQuantType == infer::DYNAMIC_QUANT_ASYMMETRIC) {
64	        ATB_LOG(ERROR) << "dynamicQuantType not support DYNAMIC_QUANT_ASYMMETRIC";
65	        return ERROR_INVALID_PARAM;
66	    }
67	    return NO_ERROR;
68	}
69	
70	Status PreNormParamCheck(infer::LayerNormParam::PreNormParam preNormParam)
71	{
72	    if (preNormParam.quantType != infer::QUANT_UNQUANT) {
73	        ATB_LOG(ERROR) << "prelayernorm does not support quant";
74	        return ERROR_INVALID_PARAM;
75	    }
76	    if (std::fabs(preNormParam.epsilon) < THRESHOLD) {
77	        ATB_LOG(ERROR) << "Invalid epsilon, it's recommended to init a nonzero value for eps.";
78	        return ERROR_INVALID_PARAM;
79	    }
80	    if (preNormParam.opMode != 0) {
81	        ATB_LOG(ERROR) << "Invalid opMode, only supports 0.";
82	        return ERROR_INVALID_PARAM;
83	    }
84	    return NO_ERROR;
85	}
86	
87	Status PostNormParamCheck(infer::LayerNormParam::PostNormParam postNormParam)
88	{
89	    if (postNormParam.quantType != infer::QUANT_UNQUANT && postNormParam.quantType != infer::QUANT_INT8) {
90	        ATB_LOG(ERROR) << "quantType is not supported, only support QUANT_UNQUANT/QUANT_INT8";
91	        return ERROR_INVALID_PARAM;
92	    }
93	    if (std::fabs(postNormParam.epsilon) < THRESHOLD) {
94	        ATB_LOG(ERROR) << "Invalid epsilon, it's recommended to init a nonzero value for eps.";
95	        return ERROR_INVALID_PARAM;
96	    }
97	    if (postNormParam.opMode != 0) {
98	        ATB_LOG(ERROR) << "Invalid opMode, only supports 0.";
99	        return ERROR_INVALID_PARAM;
100	    }
101	    return NO_ERROR;
102	}
103	
104	template <> Status CreateOperation(const infer::LayerNormParam &opParam, Operation **operation)
105	{
106	    if (operation == nullptr) {
107	        return ERROR_INVALID_PARAM;
108	    }
109	    OP_PARAM_RSV_CHECK(opParam);
110	    OP_PARAM_RSV_CHECK(opParam.normParam);
111	    OP_PARAM_RSV_CHECK(opParam.preNormParam);
112	    OP_PARAM_RSV_CHECK(opParam.postNormParam);
113	    Status paramCheckRet = NO_ERROR;
114	    if (opParam.layerType == infer::LayerNormParam::LAYER_NORM_NORM) {
115	        paramCheckRet = NormParamCheck(opParam.normParam);
116	        if (paramCheckRet != NO_ERROR) {
117	            return paramCheckRet;
118	        }
119	    } else if (opParam.layerType == infer::LayerNormParam::LAYER_NORM_PRENORM) {
120	        paramCheckRet = PreNormParamCheck(opParam.preNormParam);
121	        if (paramCheckRet != NO_ERROR) {
122	            return paramCheckRet;
123	        }
124	    } else if (opParam.layerType == infer::LayerNormParam::LAYER_NORM_POSTNORM) {
125	        paramCheckRet = PostNormParamCheck(opParam.postNormParam);
126	        if (paramCheckRet != NO_ERROR) {
127	            return paramCheckRet;
128	        }
129	    } else {
130	        ATB_LOG(ERROR) << "layerType is not supported, only support NORM/PRENORM/POSTNORM";
131	        return ERROR_INVALID_PARAM;
132	    }
133	    // Ascend950 仅支持 NORM + 无量化模式，拦截 PRENORM/POSTNORM/量化
134	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
135	        if (opParam.layerType != infer::LayerNormParam::LAYER_NORM_NORM) {
136	            ATB_LOG(ERROR) << "Ascend950 only supports LAYER_NORM_NORM, layerType: " << opParam.layerType;
137	            return ERROR_INVALID_PARAM;
138	        }
139	        if (opParam.normParam.quantType != infer::QUANT_UNQUANT) {
140	            ATB_LOG(ERROR) << "Ascend950 does not support quant, quantType: " << opParam.normParam.quantType;
141	            return ERROR_INVALID_PARAM;
142	        }
143	        Status loadStatus = LayerNormAclnnRunner::LoadMethod();
144	        if (loadStatus != NO_ERROR) {
145	            ATB_LOG(ERROR) << "LayerNormAclnnRunner LoadMethod failed";
146	            return loadStatus;
147	        }
148	    }
149	    *operation = new (std::nothrow) LayerNormOperation(opParam);
150	    if (*operation == nullptr) {
151	        ATB_LOG(ERROR) << "failed to new operation";
152	        return ERROR_OUT_OF_HOST_MEMORY;
153	    }
154	    return NO_ERROR;
155	}
