157	LayerNormOperation::LayerNormOperation(const infer::LayerNormParam &param)
158	    : OperationBase("LayerNormOperation"), param_(param)
159	{
160	    std::stringstream opIrKeySs;
161	    opIrKeySs << "LayerNormOperation";
162	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM) {
163	        opIrKeySs << "Norm";
164	        if (param_.normParam.quantType == infer::QUANT_INT8) {
165	            if (param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_UNDEFINED) {
166	                opIrKeySs << "Quant";
167	            } else if (param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_SYMMETRIC) {
168	                opIrKeySs << "SymmetricDynamicQuant";
169	            } else if (param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_ASYMMETRIC) {
170	                opIrKeySs << "AsymmetricDynamicQuant";
171	            }
172	        }
173	    } else if (param_.layerType == infer::LayerNormParam::LAYER_NORM_PRENORM) {
174	        opIrKeySs << "Prenorm";
175	    } else if (param_.layerType == infer::LayerNormParam::LAYER_NORM_POSTNORM) {
176	        opIrKeySs << "Postnorm";
177	        if (param_.postNormParam.quantType == infer::QUANT_INT8) {
178	            opIrKeySs << "Quant";
179	        }
180	    }
181	    operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr(opIrKeySs.str());
182	}
