186	uint32_t LayerNormOperation::GetInputNum() const
187	{
188	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM) {
189	        if (param_.normParam.quantType == infer::QUANT_UNQUANT) {
190	            return IN_TENSOR_COUNT_THREE;
191	        } else if (param_.normParam.quantType == infer::QUANT_INT8) {
192	            if (param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_UNDEFINED) {
193	                return IN_TENSOR_COUNT_FIVE;
194	            } else {
195	                return IN_TENSOR_COUNT_THREE;
196	            }
197	        }
198	    } else if (param_.layerType == infer::LayerNormParam::LAYER_NORM_PRENORM) {
199	        return IN_TENSOR_COUNT_FOUR;
200	    } else if (param_.layerType == infer::LayerNormParam::LAYER_NORM_POSTNORM) {
201	        return param_.postNormParam.quantType == infer::QUANT_INT8 ? IN_TENSOR_COUNT_SIX : IN_TENSOR_COUNT_FOUR;
202	    }
203	    ATB_LOG(ERROR) << GetLogPrefix() << "LayerNormType Undefined";
204	    return 0;
205	}
206	
207	uint32_t LayerNormOperation::GetOutputNum() const
208	{
209	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM) {
210	        if (param_.normParam.quantType == infer::QUANT_INT8) {
211	            if (param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_SYMMETRIC) {
212	                return OUT_TENSOR_COUNT_TWO;
213	            } else if (param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_ASYMMETRIC) {
214	                return OUT_TENSOR_COUNT_THREE;
215	            }
216	        }
217	        return 1;
218	    } else if (param_.layerType == infer::LayerNormParam::LAYER_NORM_PRENORM) {
219	        return OUT_TENSOR_COUNT_TWO;
220	    } else if (param_.layerType == infer::LayerNormParam::LAYER_NORM_POSTNORM) {
221	        if (param_.postNormParam.quantType == infer::QUANT_UNQUANT) {
222	            return 1;
223	        } else {
224	            return OUT_TENSOR_COUNT_TWO;
225	        }
226	    }
227	    ATB_LOG(ERROR) << GetLogPrefix() << "LayerNormType Undefined";
228	    return 0;
229	}
