231	Status LayerNormOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
232	                                          SVector<TensorDesc> &outTensorDescs) const
233	{
234	    outTensorDescs.at(0) = inTensorDescs.at(0);
235	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM && param_.normParam.quantType == infer::QUANT_INT8) {
236	        outTensorDescs.at(0).dtype = ACL_INT8;
237	        if (param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_UNDEFINED) {
238	            return NO_ERROR;
239	        }
240	        outTensorDescs.at(1) = inTensorDescs.at(0);
241	        outTensorDescs.at(1).shape.dimNum--;
242	        outTensorDescs.at(1).dtype = ACL_FLOAT;
243	        if (param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_ASYMMETRIC) {
244	            outTensorDescs.at(2) = outTensorDescs.at(1); // 2: offset
245	        }
246	    }
247	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_PRENORM) {
248	        outTensorDescs.at(1) = inTensorDescs.at(0);
249	    }
250	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_POSTNORM) {
251	        if (param_.postNormParam.quantType == infer::QUANT_INT8) {
252	            outTensorDescs.at(1) = inTensorDescs.at(0);
253	            outTensorDescs.at(1).dtype = ACL_INT8;
254	        }
255	    }
256	    return NO_ERROR;
257	}
258	
259	Status LayerNormOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
260	{
261	    const TensorDesc &xTensorDesc = inTensorDescs.at(0);
262	    const TensorDesc &gammaTensorDesc = param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM ?
263	                                            inTensorDescs.at(1) :
264	                                            inTensorDescs.at(IN_TENSOR_GAMMA_PRE_POSTNORM);
265	    Status checkStatus = ParamCheck(xTensorDesc, gammaTensorDesc);
266	    if (checkStatus != NO_ERROR) {
267	        return checkStatus;
268	    }
269	    checkStatus = InTensorsDimCheck(inTensorDescs);
270	    if (checkStatus != NO_ERROR) {
271	        return checkStatus;
272	    }
273	    checkStatus = LastDimCheck(inTensorDescs);
274	    if (checkStatus != NO_ERROR) {
275	        return checkStatus;
276	    }
277	    if ((param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM &&
278	         param_.normParam.quantType == infer::QUANT_INT8 &&
279	         param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_UNDEFINED) ||
280	        (param_.layerType == infer::LayerNormParam::LAYER_NORM_POSTNORM &&
281	         param_.postNormParam.quantType == infer::QUANT_INT8)) {
282	        if (!QuantTensorCheck(inTensorDescs)) {
283	            ATB_LOG(ERROR) << GetLogPrefix() << "quant tensor shape error";
284	            return ERROR_INVALID_TENSOR_SIZE;
285	        }
286	    }
287	    return NO_ERROR;
288	}
289	
290	Status LayerNormOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
291	{
292	    const TensorDesc &xTensorDesc = inTensors.at(0).desc;
293	    const TensorDesc &gammaTensorDesc = param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM ?
294	                                            inTensors.at(1).desc :
295	                                            inTensors.at(IN_TENSOR_GAMMA_PRE_POSTNORM).desc;
296	    Status paramCheckStatus = ParamCheck(xTensorDesc, gammaTensorDesc);
297	    if (paramCheckStatus != NO_ERROR) {
298	        return paramCheckStatus;
299	    }
300	    SVector<TensorDesc> inTensorDescs;
301	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
302	    SVector<TensorDesc> outTensorDescs;
303	    OperationUtil::InTensorsToInTensorDescs(outTensors, outTensorDescs);
304	    Status lastDimCheckStatus = LastDimCheck(inTensorDescs);
305	    if (lastDimCheckStatus != NO_ERROR) {
306	        return lastDimCheckStatus;
307	    }
308	    uint32_t out_num = GetOutputNum();
309	    SVector<TensorDesc> targetOutTensorDescs = {};
310	    targetOutTensorDescs.reserve(out_num);
311	    targetOutTensorDescs.resize(out_num);
312	    InferShapeImpl(inTensorDescs, targetOutTensorDescs);
313	    for (size_t i = 0; i < out_num; ++i) {
314	        if (!TensorUtil::TensorDescEqual(outTensorDescs.at(i), targetOutTensorDescs.at(i))) {
315	            ATB_LOG(ERROR) << GetLogPrefix() << "dims of outTensors does not match";
316	            return ERROR_INVALID_TENSOR_DIM;
317	        }
318	    }
319	    return NO_ERROR;
320	}
321	
322	Status LayerNormOperation::ParamCheck(const TensorDesc &xTensorDesc, const TensorDesc &gammaTensorDesc) const
323	{
324	    int32_t beginNormAxis = param_.normParam.beginNormAxis;
325	    uint64_t xTensorDimNum = xTensorDesc.shape.dimNum;
326	    uint64_t gammaTensorDimNum = gammaTensorDesc.shape.dimNum;
327	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM &&
328	        param_.normParam.quantType == infer::QUANT_UNQUANT) {
329	        if (gammaTensorDimNum > xTensorDimNum) {
330	            ATB_LOG(ERROR) << GetLogPrefix() << "gammaTensor dimNum should be smaller or equal to xTensor.";
331	            return ERROR_INVALID_TENSOR_DIM;
332	        }
333	        if (beginNormAxis >= 0 && static_cast<uint64_t>(beginNormAxis) + gammaTensorDimNum != xTensorDimNum) {
334	            ATB_LOG(ERROR) << GetLogPrefix() << "beginNormAxis(" << beginNormAxis << ") + gammaTensorDimNum("
335	                           << gammaTensorDimNum << ") != xTensorDimNum(" << xTensorDimNum
336	                           << "), beginNormAxis must make remaining dims match gamma shape";
337	            return ERROR_INVALID_PARAM;
338	        }
339	        if (beginNormAxis < 0 && static_cast<uint64_t>(-beginNormAxis) != gammaTensorDimNum) {
340	            ATB_LOG(ERROR) << GetLogPrefix() << "beginNormAxis(" << beginNormAxis << ") is negative, abs value ("
341	                           << -beginNormAxis << ") must equal gammaTensorDimNum(" << gammaTensorDimNum << ")";
342	            return ERROR_INVALID_PARAM;
343	        }
344	    }
345	    return NO_ERROR;
346	}
