348	std::shared_ptr<Runner> LayerNormOperation::CreateRunner(Context &context) const
349	{
350	    (void)context;
351	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950 &&
352	        param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM &&
353	        param_.normParam.quantType == infer::QUANT_UNQUANT) {
354	        return std::make_shared<LayerNormAclnnRunner>(param_);
355	    }
356	    return std::make_shared<LayerNormOpsRunner>(param_);
357	}
