363	
364	bool LayerNormOperation::QuantTensorCheck(const SVector<TensorDesc> &inTensorDescs) const
365	{
366	    uint32_t scaleIndex = 0;
367	    uint32_t offsetIndex = 0;
368	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM) {
369	        scaleIndex = IN_TENSOR_SCALE_NORMNORM;
370	        offsetIndex = IN_TENSOR_OFFSET_NORMNORM;
371	    } else if (param_.layerType == infer::LayerNormParam::LAYER_NORM_POSTNORM) {
372	        scaleIndex = IN_TENSOR_SCALE_POSTNORM;
373	        offsetIndex = IN_TENSOR_OFFSET_POSTNORM;
374	    }
375	    const TensorDesc scaleInTensorDesc = inTensorDescs.at(scaleIndex);
376	    const TensorDesc offsetInTensorDesc = inTensorDescs.at(offsetIndex);
377	    if (scaleInTensorDesc.shape.dimNum != 1 || offsetInTensorDesc.shape.dimNum != 1) {
378	        ATB_LOG(ERROR) << GetLogPrefix() << "dim numbers of quant param intensors should be one";
379	        return false;
380	    }
381	    if (scaleInTensorDesc.shape.dims[0] != 1 || offsetInTensorDesc.shape.dims[0] != 1) {
382	        ATB_LOG(ERROR) << GetLogPrefix() << "dim sizes of quant param intensors should be one";
383	        return false;
384	    }
385	    return true;
386	}
387	
388	Status LayerNormOperation::LastDimCheck(const SVector<TensorDesc> &inTensorDescs) const
389	{
390	    uint64_t dimNum = inTensorDescs.at(0).shape.dimNum;
391	    int64_t lastDim = inTensorDescs.at(0).shape.dims[dimNum - 1];
392	    // only layernorm no quant has no restriction on alignment
393	    if (!(param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM &&
394	          param_.normParam.quantType == infer::QUANT_UNQUANT)) {
395	        if ((static_cast<uint64_t>(lastDim) % static_cast<uint64_t>(ALIGNMENT / sizeof(uint16_t))) != 0) {
396	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensor shape is not support, should align 32";
397	            return ERROR_INVALID_TENSOR_SIZE;
398	        }
399	    }
400	    uint32_t inTensorCount = GetInputNum();
401	    if ((param_.normParam.quantType == infer::QUANT_INT8 &&
402	         param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_UNDEFINED) ||
403	        param_.postNormParam.quantType == infer::QUANT_INT8) {
404	        inTensorCount -= QUANT_TENSOR_COUNT;
405	    }
406	    for (uint32_t i = 1; i < inTensorCount; i++) {
407	        dimNum = inTensorDescs.at(i).shape.dimNum;
408	        if ((inTensorDescs.at(i).shape.dims[dimNum - 1]) != lastDim) {
409	            ATB_LOG(ERROR) << GetLogPrefix() << "last dims of inTensors does not match";
410	            return ERROR_INVALID_TENSOR_SIZE;
411	        }
412	    }
413	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM &&
414	        param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_SYMMETRIC &&
415	        lastDim > DYNAMIC_QUANT_MAX_TENSOR_LENGTH) {
416	        ATB_LOG(ERROR) << GetLogPrefix() << "Length of the last dim is invalid, it should be no larger than "
417	                       << DYNAMIC_QUANT_MAX_TENSOR_LENGTH << ".";
418	        return ERROR_INVALID_TENSOR_SIZE;
419	    }
420	    return NO_ERROR;
421	}
422	
423	Status LayerNormOperation::InTensorsDimCheck(const SVector<TensorDesc> inTensorDescs) const
424	{
425	    Status result = NO_ERROR;
426	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_NORM && param_.normParam.quantType == infer::QUANT_INT8 &&
427	        param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_SYMMETRIC && inTensorDescs.at(0).shape.dimNum < 2) {
428	        ATB_LOG(ERROR) << GetLogPrefix() << "dim numbers of inTensor[0] should be greater than one";
429	        return ERROR_INVALID_TENSOR_DIM;
430	    }
431	    if (param_.layerType == infer::LayerNormParam::LAYER_NORM_PRENORM ||
432	        param_.layerType == infer::LayerNormParam::LAYER_NORM_POSTNORM) {
433	        result = TensorCheck::TensorDescsEqual(inTensorDescs.at(X_TENSOR), inTensorDescs.at(RESIDUAL_IN_TENSOR));
434	        if (result != NO_ERROR) {
435	            ATB_LOG(ERROR) << GetLogPrefix() << "Residual tensor should be the same as x tensor.";
436	            return result;
437	        }
438	    }
439	    return result;
440	}
441	} // namespace atb

