105	        if (opParam.normParam.quantType == infer::QUANT_UNQUANT || opParam.normParam.quantType == infer::QUANT_INT8) {
106	            return true;
107	        }
108	        error.errorData = OperationUtil::ConcatInfo(error.errorData, ", quantType = ", opParam.normParam.quantType);
109	    } else if (opParam.layerType == infer::RmsNormParam::RMS_NORM_PRENORM) {
110	        if (opParam.preNormParam.quantType == infer::QUANT_UNQUANT ||
111	            opParam.preNormParam.quantType == infer::QUANT_INT8) {
112	            return true;
113	        }
114	        error.errorData = OperationUtil::ConcatInfo(error.errorData, ", quantType = ", opParam.preNormParam.quantType);
115	    } else if (opParam.layerType == infer::RmsNormParam::RMS_NORM_POSTNORM) {
116	        if (opParam.postNormParam.quantType == infer::QUANT_UNQUANT ||
117	            opParam.postNormParam.quantType == infer::QUANT_INT8) {
118	            return true;
119	        }
120	        error.errorData = OperationUtil::ConcatInfo(error.errorData, ", quantType = ", opParam.postNormParam.quantType);
121	    }
122	    error.solutionDesc = "Please check the document for valid layerType and quantType.";
123	    ATB_LOG(ERROR) << error;
124	    return false;
125	}
