127	template <> Status CreateOperation(const infer::RmsNormParam &opParam, Operation **operation)
128	{
129	    if (operation == nullptr) {
130	        return ERROR_INVALID_PARAM;
131	    }
132	    OP_PARAM_RSV_CHECK(opParam);
133	    OP_PARAM_RSV_CHECK(opParam.normParam);
134	    OP_PARAM_RSV_CHECK(opParam.preNormParam);
135	    OP_PARAM_RSV_CHECK(opParam.postNormParam);
136	
137	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
138	        Status st = RmsNormAclnnRunner::LoadAclnnFuncs();
139	        if (st != NO_ERROR) {
140	            ATB_LOG(ERROR) << "RmsNormAclnnRunner load aclnn functions failed!";
141	            return st;
142	        }
143	        st = AddRmsNormAclnnRunner::LoadAclnnFuncs();
144	        if (st != NO_ERROR) {
145	            ATB_LOG(ERROR) << "AddRmsNormAclnnRunner load aclnn functions failed!";
146	            return st;
147	        }
148	        st = RmsNormQuantAclnnRunner::LoadAclnnFuncs();
149	        if (st != NO_ERROR) {
150	            ATB_LOG(ERROR) << "RmsNormQuantAclnnRunner load aclnn functions failed!";
151	            return st;
152	        }
153	    }
154	
155	    ATB_LOG(INFO) << "CreateOperation with RmsNormParam: " << OpParamToJson(opParam);
156	    if (!EpsilonCheck(opParam)) {
157	        ATB_LOG(ERROR) << "Invalid epsilon, it's recommended to init a nonzero value for eps.";
158	        return ERROR_INVALID_PARAM;
159	    }
160	    if (!RmsNormTypeCheck(opParam)) {
161	        return ERROR_INVALID_PARAM;
162	    }
163	    if (opParam.layerType == infer::RmsNormParam::RMS_NORM_NORM &&
164	        opParam.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_ASYMMETRIC) {
165	        ATB_LOG(ERROR) << "dynamicQuantType not support DYNAMIC_QUANT_ASYMMETRIC";
166	        return ERROR_INVALID_PARAM;
167	    }
168	    *operation = new (std::nothrow) RmsNormOperation(opParam);
169	    if (*operation == nullptr) {
170	        ATB_LOG(ERROR) << "failed to new operation";
171	        return ERROR_OUT_OF_HOST_MEMORY;
172	    }
173	    return NO_ERROR;
174	}
