230	uint32_t RmsNormOperation::GetInputNum() const
231	{
232	    if (param_.layerType == infer::RmsNormParam::RMS_NORM_NORM) {
233	        if (param_.normParam.quantType == infer::QUANT_UNQUANT) {
234	            return IN_TENSOR_COUNT_TWO;
235	        }
236	        if (param_.normParam.quantType == infer::QUANT_INT8) {
237	            return param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_UNDEFINED ? IN_TENSOR_COUNT_FIVE :
238	                                                                                         IN_TENSOR_COUNT_THREE;
239	        }
240	    } else if (param_.layerType == infer::RmsNormParam::RMS_NORM_PRENORM &&
241	               param_.preNormParam.quantType == infer::QUANT_INT8) {
242	        return IN_TENSOR_COUNT_SIX;
243	    } else if (param_.layerType == infer::RmsNormParam::RMS_NORM_POSTNORM &&
244	               param_.postNormParam.quantType == infer::QUANT_INT8) {
245	        return IN_TENSOR_COUNT_FIVE;
246	    } else if ((param_.layerType == infer::RmsNormParam::RMS_NORM_POSTNORM &&
247	                param_.postNormParam.quantType == infer::QUANT_UNQUANT) ||
248	               (param_.layerType == infer::RmsNormParam::RMS_NORM_PRENORM &&
249	                param_.preNormParam.quantType == infer::QUANT_UNQUANT)) {
250	        return param_.preNormParam.hasBias || param_.postNormParam.hasBias ? IN_TENSOR_COUNT_FOUR :
251	                                                                             IN_TENSOR_COUNT_THREE;
252	    } else {
253	        ATB_LOG(ERROR) << GetLogPrefix() << "RmsNormType Undefined";
254	    }
255	    return 0;
