270	        }
271	        if (param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_ASYMMETRIC) {
272	            return OUT_TENSOR_COUNT_THREE;
273	        }
274	    } else if (param_.layerType == infer::RmsNormParam::RMS_NORM_PRENORM &&
275	               (param_.preNormParam.quantType == infer::QUANT_INT8 ||
276	                param_.preNormParam.quantType == infer::QUANT_UNQUANT)) {
