290	Status RmsNormOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
291	                                        SVector<TensorDesc> &outTensorDescs) const
292	{
293	    outTensorDescs.at(0) = inTensorDescs.at(0);
294	    if (param_.layerType == infer::RmsNormParam::RMS_NORM_NORM && param_.normParam.quantType == infer::QUANT_INT8) {
295	        outTensorDescs.at(0).dtype = ACL_INT8;
296	        if (param_.normParam.dynamicQuantType != infer::DYNAMIC_QUANT_UNDEFINED) {
297	            outTensorDescs.at(1) = inTensorDescs.at(0);
298	            outTensorDescs.at(1).shape.dimNum--;
299	            outTensorDescs.at(1).dtype = ACL_FLOAT;
300	            if (param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_ASYMMETRIC) {
301	                outTensorDescs.at(2) = outTensorDescs.at(1); // 2: offset
302	            }
303	        }
304	    }
305	    if (param_.layerType == infer::RmsNormParam::RMS_NORM_NORM && param_.normParam.rstd) {
306	        outTensorDescs.at(OUT_TENSOR_RSTD) = inTensorDescs.at(IN_TENSOR_X);
307	        outTensorDescs.at(OUT_TENSOR_RSTD).dtype = ACL_FLOAT;
308	        size_t xDimNum = inTensorDescs.at(IN_TENSOR_X).shape.dimNum;
309	        size_t gammaDimNum = inTensorDescs.at(IN_TENSOR_GAMMA).shape.dimNum;
310	        for (size_t i = 0; i < gammaDimNum; i++) {
311	            outTensorDescs[OUT_TENSOR_RSTD].shape.dims[xDimNum - gammaDimNum + i] = 1;
312	        }
313	    }
314	    if (param_.layerType == infer::RmsNormParam::RMS_NORM_PRENORM &&
315	        param_.preNormParam.quantType == infer::QUANT_INT8) {
316	        outTensorDescs.at(0).dtype = ACL_INT8;
317	        outTensorDescs.at(1) = inTensorDescs.at(0);
318	    }
319	    if (param_.layerType == infer::RmsNormParam::RMS_NORM_PRENORM &&
320	        param_.preNormParam.quantType == infer::QUANT_UNQUANT) {
321	        outTensorDescs.at(1) = inTensorDescs.at(0);
322	    }
323	    if (param_.layerType == infer::RmsNormParam::RMS_NORM_POSTNORM &&
324	        param_.postNormParam.quantType == infer::QUANT_INT8) {
325	        outTensorDescs.at(1) = inTensorDescs.at(0);
326	        outTensorDescs.at(0).dtype = ACL_INT8;
327	    }
328	    return NO_ERROR;
329	}
