331	Status RmsNormOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
332	{
333	    if (!DtypeCheck(inTensorDescs.at(IN_TENSOR_X).dtype)) {
334	        return ERROR_INVALID_TENSOR_DTYPE;
335	    }
336	    if (param_.layerType == infer::RmsNormParam::RMS_NORM_NORM) {
337	        if (param_.normParam.rstd) {
338	            if (!NormForwardInferShapeCheckImpl(inTensorDescs)) {
339	                return ERROR_INVALID_TENSOR_DIM;
340	            }
341	        } else {
342	            if (!NormInferShapeCheckImpl(inTensorDescs)) {
343	                return ERROR_INVALID_TENSOR_DIM;
344	            }
345	        }
346	    } else if ((param_.layerType == infer::RmsNormParam::RMS_NORM_POSTNORM &&
347	                param_.postNormParam.quantType == infer::QUANT_UNQUANT) ||
348	               (param_.layerType == infer::RmsNormParam::RMS_NORM_PRENORM &&
349	                param_.preNormParam.quantType == infer::QUANT_UNQUANT)) {
350	        if (!AddRMSNormInferShapeCheckImpl(inTensorDescs)) {
351	            return ERROR_INVALID_TENSOR_DIM;
352	        }
353	    } else {
354	        if (param_.layerType == infer::RmsNormParam::RMS_NORM_POSTNORM &&
355	            param_.postNormParam.quantType == infer::QUANT_INT8) {
356	            if (!PostnormInferShapeCheckImpl(inTensorDescs)) {
357	                return ERROR_INVALID_TENSOR_DIM;
358	            }
359	        } else if (!PrenormInferShapeCheckImpl(inTensorDescs)) {
360	            return ERROR_INVALID_TENSOR_DIM;
361	        }
362	    }
363	    if (!CheckLastDims(inTensorDescs)) {
364	        bool isPostQuant = (param_.postNormParam.quantType == infer::QUANT_INT8);
365	        return isPostQuant ? ERROR_INVALID_TENSOR_DIM : ERROR_INVALID_TENSOR_SIZE;
366	    }
367	    return ParamCheck();
368	}
