370	Status RmsNormOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
371	{
372	    SVector<TensorDesc> inTensorDescs;
373	    for (size_t i = 0; i < inTensors.size(); i++) {
374	        inTensorDescs.push_back(inTensors.at(i).desc);
375	    }
376	    aclDataType targetType = inTensorDescs[IN_TENSOR_X].dtype;
377	    if (param_.normParam.quantType == infer::QUANT_INT8 || param_.preNormParam.quantType == infer::QUANT_INT8 ||
378	        param_.postNormParam.quantType == infer::QUANT_INT8) {
379	        targetType = ACL_INT8;
380	    }
381	    Status st = CheckOutTensorSame(inTensorDescs[IN_TENSOR_X], outTensors[OUT_TENSOR_X].desc, targetType);
382	    if (st != NO_ERROR) {
383	        return st;
384	    }
385	    if (param_.preNormParam.quantType == infer::QUANT_INT8 || param_.postNormParam.quantType == infer::QUANT_INT8) {
386	        targetType = inTensorDescs[IN_TENSOR_X].dtype;
387	        st = CheckOutTensorSame(inTensorDescs[IN_TENSOR_X], outTensors[OUT_TENSOR_QAUNT].desc, targetType);
388	        if (st != NO_ERROR) {
389	            return st;
390	        }
391	    }
392	    if (param_.normParam.rstd) {
393	        st = CheckRstdOutTensor(inTensorDescs, outTensors[OUT_TENSOR_RSTD].desc);
394	        if (st != NO_ERROR) {
395	            return st;
396	        }
397	    }
398	    return InferShapeCheckImpl(inTensorDescs);
399	}
