510	bool RmsNormOperation::NormInferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
511	{
512	    TensorDesc xTensorDesc = inTensorDescs.at(0);
513	    TensorDesc gammaTensorDesc = inTensorDescs.at(1);
514	    uint64_t xDimNum = xTensorDesc.shape.dimNum;
515	    uint64_t gammaDimNum = gammaTensorDesc.shape.dimNum;
516	    if (xTensorDesc.shape.dims[xDimNum - 1] != gammaTensorDesc.shape.dims[gammaDimNum - 1]) {
517	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor0 lastDim == inTensor1 lastDim";
518	        return false;
519	    }
520	    for (uint64_t i = 0; i < gammaTensorDesc.shape.dimNum - 1; i++) {
521	        if (gammaTensorDesc.shape.dims[i] != 1) {
522	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor1 dimsExceptLastDim == 1";
523	            return false;
524	        }
525	    }
526	    if (param_.normParam.quantType == infer::QUANT_INT8 &&
527	        param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_UNDEFINED) {
528	        TensorDesc betaTensorDesc = inTensorDescs.at(2);
529	        if (TensorDescsDiff(gammaTensorDesc, betaTensorDesc)) {
530	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensor2 dims error, inTensor1 dims == inTensor2 dims";
531	            return false;
532	        }
533	        // 兼容intensor传入quant参数
534	        const TensorDesc &scaleTensorDesc = inTensorDescs.at(IN_TENSOR_SCALE);
535	        const TensorDesc &offsetTensorDesc = inTensorDescs.at(IN_TENSOR_OFFSET);
536	        if (!QuantTensorsCheck(scaleTensorDesc, offsetTensorDesc)) {
537	            ATB_LOG(ERROR) << GetLogPrefix() << "quant tensor shape error";
538	            return false;
539	        }
540	    }
541	    return true;
542	}
543	
544	bool RmsNormOperation::NormForwardInferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
545	{
546	    auto xDim = inTensorDescs.at(IN_TENSOR_X).shape.dims;
547	    auto gammaDim = inTensorDescs.at(IN_TENSOR_GAMMA).shape.dims;
548	    int32_t xDimNum = inTensorDescs.at(IN_TENSOR_X).shape.dimNum;
549	    int32_t gammaDimNum = inTensorDescs.at(IN_TENSOR_GAMMA).shape.dimNum;
550	    int32_t startDim = xDimNum - gammaDimNum;
551	    if (startDim < 0) {
552	        ATB_LOG(ERROR) << GetLogPrefix() << "gamma's dimnum invalid";
553	        return false;
554	    }
555	    for (int32_t i = startDim; i < xDimNum; i++) {
556	        if (xDim[i] != gammaDim[i - startDim]) {
557	            ATB_LOG(ERROR) << GetLogPrefix() << "gamma shape invalid";
558	            return false;
559	        }
560	    }
561	    return true;
562	}
563	
564	bool RmsNormOperation::PrenormInferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
565	{
566	    TensorDesc xTensorDesc = inTensorDescs.at(0);
567	    TensorDesc resInTensorDesc = inTensorDescs.at(1);
568	    TensorDesc gammaTensorDesc = inTensorDescs.at(2);
569	    TensorDesc betaTensorDesc = inTensorDescs.at(3);
570	    if (TensorDescsDiff(xTensorDesc, resInTensorDesc) || TensorDescsDiff(gammaTensorDesc, betaTensorDesc)) {
571	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor0 == inTensor1, inTensor2 == inTensor3";
572	        return false;
573	    }
574	    if (xTensorDesc.shape.dims[xTensorDesc.shape.dimNum - 1] !=
575	        gammaTensorDesc.shape.dims[gammaTensorDesc.shape.dimNum - 1]) {
576	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor0 lastDim == inTensor2 lastDim";
577	        return false;
578	    }
579	    for (uint64_t i = 0; i < gammaTensorDesc.shape.dimNum - 1; i++) {
580	        if (gammaTensorDesc.shape.dims[i] != 1) {
581	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor2 dimsExceptLastDim == 1";
582	            return false;
583	        }
584	    }
585	    const TensorDesc &scaleTensorDesc = inTensorDescs.at(IN_TENSOR_SCALE_PRENORM);
586	    const TensorDesc &offsetTensorDesc = inTensorDescs.at(IN_TENSOR_OFFSET_PRENORM);
587	    if (!QuantTensorsCheck(scaleTensorDesc, offsetTensorDesc)) {
588	        ATB_LOG(ERROR) << GetLogPrefix() << "quant tensor shape error";
589	        return false;
590	    }
591	    return true;
592	}
593	
594	bool RmsNormOperation::PostnormInferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
595	{
596	    TensorDesc xTensorDesc = inTensorDescs.at(0);
597	    TensorDesc resInTensorDesc = inTensorDescs.at(1);
598	    TensorDesc gammaTensorDesc = inTensorDescs.at(2);
599	    if (TensorDescsDiff(xTensorDesc, resInTensorDesc)) {
600	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor0 == inTensor1, inTensor2 == inTensor3";
601	        return false;
602	    }
603	    if (xTensorDesc.shape.dims[xTensorDesc.shape.dimNum - 1] !=
604	        gammaTensorDesc.shape.dims[gammaTensorDesc.shape.dimNum - 1]) {
605	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor0 lastDim == inTensor2 lastDim";
606	        return false;
607	    }
608	    if (gammaTensorDesc.shape.dimNum != GAMMA_DIM_TWO &&
609	        (gammaTensorDesc.shape.dimNum != GAMMA_DIM_ONE && param_.postNormParam.quantType == infer::QUANT_INT8)) {
610	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, gammainTensor dimsExceptDimNum == 1 or 2";
611	        return false;
612	    }
613	    for (uint64_t i = 0; i < gammaTensorDesc.shape.dimNum - 1; i++) {
614	        if (gammaTensorDesc.shape.dims[i] != 1) {
615	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor2 dimsExceptLastDim == 1";
616	            return false;
617	        }
618	    }
619	    const TensorDesc &scaleTensorDesc = inTensorDescs.at(IN_TENSOR_SCALE);
620	    const TensorDesc &offsetTensorDesc = inTensorDescs.at(IN_TENSOR_OFFSET);
621	    if (!QuantTensorsCheck(scaleTensorDesc, offsetTensorDesc)) {
622	        ATB_LOG(ERROR) << GetLogPrefix() << "quant tensor shape error";
623	        return false;
624	    }
625	    return true;
626	}
627	
628	bool RmsNormOperation::AddRMSNormInferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
629	{
630	    uint32_t idx = 0;
631	    bool hasBias = param_.preNormParam.hasBias || param_.postNormParam.hasBias;
632	    TensorDesc xTensorDesc = inTensorDescs.at(idx++);
633	    TensorDesc biasTensorDesc;
634	    if (hasBias) {
635	        biasTensorDesc = inTensorDescs.at(idx++);
636	    }
637	    TensorDesc resInTensorDesc = inTensorDescs.at(idx++);
638	    TensorDesc gammaTensorDesc = inTensorDescs.at(idx++);
639	    if (TensorDescsDiff(xTensorDesc, resInTensorDesc)) {
640	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor0 == inTensor1, inTensor2 == inTensor3";
641	        return false;
642	    }
643	    if (!GammaBetaTensorCheck(xTensorDesc, gammaTensorDesc)) {
644	        ATB_LOG(ERROR) << GetLogPrefix() << "gammaTensorDesc error";
645	        return false;
646	    }
647	    if (hasBias && !GammaBetaTensorCheck(xTensorDesc, biasTensorDesc)) {
648	        ATB_LOG(ERROR) << GetLogPrefix() << "biasTensorDesc error";
649	        return false;
650	    }
651	    return true;
652	}
653	
654	bool TensorDescsDiff(const TensorDesc &tensorDesc1, const TensorDesc &tensorDesc2)
655	{
656	    if (tensorDesc1.dtype != tensorDesc2.dtype || tensorDesc1.format != tensorDesc2.format ||
657	        tensorDesc1.shape.dimNum != tensorDesc2.shape.dimNum) {
658	        return true;
659	    }
660	    for (uint64_t i = 0; i < tensorDesc1.shape.dimNum; i++) {
661	        if (tensorDesc1.shape.dims[i] != tensorDesc2.shape.dims[i]) {
662	            return true;
663	        }
664	    }
665	    return false;
666	}
667	
668	Status RmsNormOperation::CheckOutTensorSame(const TensorDesc &tensorDesc1, const TensorDesc &tensorDesc2,
669	                                            const aclDataType &targetType) const
670	{
671	    if (targetType != tensorDesc2.dtype) {
672	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensor dtype is invalid";
673	        return ERROR_INVALID_TENSOR_DTYPE;
674	    }
675	    if (tensorDesc1.format != tensorDesc2.format) {
676	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensor format is invalid";
677	        return ERROR_INVALID_TENSOR_FORMAT;
678	    }
679	    if (tensorDesc1.shape.dimNum != tensorDesc2.shape.dimNum) {
680	        ATB_LOG(ERROR) << GetLogPrefix() << "outTensor dimNum is invalid";
681	        return ERROR_INVALID_TENSOR_SIZE;
682	    }
683	    for (uint64_t i = 0; i < tensorDesc1.shape.dimNum; i++) {
684	        if (tensorDesc1.shape.dims[i] != tensorDesc2.shape.dims[i]) {
685	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor dims are invalid";
686	            return ERROR_INVALID_TENSOR_DIM;
687	        }
688	    }
689	    return NO_ERROR;
690	}
691	
692	Status RmsNormOperation::CheckRstdOutTensor(const SVector<TensorDesc> &inTensorDescs,
693	                                            const TensorDesc &rsdtTensorDesc) const
694	{
695	    TensorDesc xTensorDesc = inTensorDescs[IN_TENSOR_X];
696	    TensorDesc gammaTensorDesc = inTensorDescs[IN_TENSOR_GAMMA];
697	    uint64_t xDimNum = xTensorDesc.shape.dimNum;
698	    uint64_t gammaDimNum = gammaTensorDesc.shape.dimNum;
699	    for (uint64_t i = 0; i < xDimNum; i++) {
700	        if (i < xDimNum - gammaDimNum && xTensorDesc.shape.dims[i] != rsdtTensorDesc.shape.dims[i]) {
701	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor rstd dim does not match the shape of x inTensor.";
702	            return ERROR_INVALID_TENSOR_DIM;
703	        } else if (i >= xDimNum - gammaDimNum && rsdtTensorDesc.shape.dims[i] != TENSOR_DIM_ONE) {
704	            ATB_LOG(ERROR) << GetLogPrefix() << "size of dim which larger than xDimNum - gammaNum should be 1.";
705	            return ERROR_INVALID_TENSOR_DIM;
706	        }
707	    }
708	    return NO_ERROR;
709	}
710	
711	bool RmsNormOperation::GammaBetaTensorCheck(const TensorDesc &xTensorDesc, const TensorDesc &tensorDesc2) const
712	{
713	    int embedDim = xTensorDesc.shape.dims[xTensorDesc.shape.dimNum - 1];
714	    if (xTensorDesc.dtype != tensorDesc2.dtype || xTensorDesc.format != tensorDesc2.format) {
715	        ATB_LOG(ERROR) << GetLogPrefix() << "gamma and bias should have the same dtype and format as x";
716	        return false;
717	    }
718	    if (tensorDesc2.shape.dims[tensorDesc2.shape.dimNum - 1] != embedDim) {
719	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor last dim is not equal to embed_dim";
720	        return false;
721	    }
722	    for (uint64_t i = 0; i < tensorDesc2.shape.dimNum - 1; i++) {
723	        if (tensorDesc2.shape.dims[i] != 1) {
724	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensors dims error, inTensor non-last dim is not equal to 1";
725	            return false;
726	        }
727	    }
728	    return true;
729	}
730	
731	// 兼容intensor传入quant参数
732	bool RmsNormOperation::QuantTensorsCheck(const TensorDesc &scaleTensorDesc, const TensorDesc &offsetTensorDesc) const
733	{
734	    if (scaleTensorDesc.shape.dimNum != TENSOR_DIM_ONE || offsetTensorDesc.shape.dimNum != TENSOR_DIM_ONE) {
735	        ATB_LOG(ERROR) << GetLogPrefix() << "scaleTensor and offsetTensor dim number should be one";
736	        return false;
737	    }
738	    if (scaleTensorDesc.shape.dims[0] != DIM_SHAPE_ONE || offsetTensorDesc.shape.dims[0] != DIM_SHAPE_ONE) {
739	        ATB_LOG(ERROR) << GetLogPrefix() << "scaleTensor and offsetTensor dim size should be one";
740	        return false;
741	    }
742	    return true;
743	}
744	
745	bool RmsNormOperation::CheckLastDims(const SVector<TensorDesc> &inTensorDescs) const
746	{
747	    uint32_t inTensorCount = GetInputNum();
748	    if (param_.normParam.quantType == infer::QUANT_INT8 || param_.preNormParam.quantType == infer::QUANT_INT8 ||
749	        param_.postNormParam.quantType == infer::QUANT_INT8) {
750	        inTensorCount -= QUANT_TENSOR_COUNT;
751	    }
752	    uint64_t dimNum = inTensorDescs.at(IN_TENSOR_X).shape.dimNum;
753	    int64_t lastDim = inTensorDescs.at(IN_TENSOR_X).shape.dims[dimNum - 1];
754	    uint32_t dtypeSize = inTensorDescs.at(IN_TENSOR_X).dtype == ACL_FLOAT ? sizeof(uint32_t) : sizeof(uint16_t);
755	    if (param_.postNormParam.quantType == infer::QUANT_INT8) {
756	        if ((static_cast<uint64_t>(lastDim) % static_cast<uint64_t>(ALIGNMENT) != 0)) {
757	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensor shape is not support, should align 32";
758	            return false;
759	        }
760	    }
761	    if ((static_cast<uint64_t>(lastDim) % static_cast<uint64_t>(ALIGNMENT / dtypeSize) != 0)) {
762	        ATB_LOG(ERROR) << GetLogPrefix() << "inTensor shape is not support, should align 32";
763	        return false;
764	    }
765	    if (param_.normParam.quantType == infer::QUANT_INT8) {
766	        if ((inTensorDescs.at(IN_TENSOR_X).shape.dims[dimNum - 1]) > DYNAMIC_QUANT_MAX_TENSOR_LENGTH &&
767	            param_.normParam.dynamicQuantType == infer::DYNAMIC_QUANT_SYMMETRIC) {
768	            ATB_LOG(ERROR) << GetLogPrefix() << "Length of the last dim is invalid, it should be no larger than "
769	                           << DYNAMIC_QUANT_MAX_TENSOR_LENGTH << ".";
770	            return false;
771	        }
772	    }
773	    for (uint32_t i = 1; i < inTensorCount; i++) {
774	        dimNum = inTensorDescs.at(i).shape.dimNum;
775	        if ((inTensorDescs.at(i).shape.dims[dimNum - 1]) != lastDim) {
776	            ATB_LOG(ERROR) << GetLogPrefix() << "last dims of inTensors does not match";
777	            return false;
778	        }
779	    }
780	    return true;
781	}
782	
783	nlohmann::json RmsNormOperation::GetParamJson() const
784	{
785	    return OpParamToJson(param_);
786	}
787	} // namespace atb
