#include "rms_norm_operation.h"
#include <mki/utils/platform/platform_info.h>
#include <cmath>
#include "atb/utils/tensor_check.h"
#include "atb/utils/param_to_json.h"
#include "atb/utils/config.h"
#include "atb/utils/singleton.h"
