23	static const uint32_t IN_TENSOR_NUM = 2;
24	static const uint32_t OUT_TENSOR_NUM = 1;
25	static const uint32_t X_TENSOR_NUM = 0;
26	static const uint32_t GAMMA_TENSOR_NUM = 1;
27	static const uint32_t LAST_ONE_NUM = 1;
28	static const uint32_t LAST_TWO_NUM = 2;
29	static const uint32_t ALIGNMENT = 16;
30	static const uint32_t DIM_NUM_TWO = 2;
31	static const uint32_t DIM_NUM_THREE = 3;
32	static const uint32_t DIM_NUM_FOUR = 4;
33	static const float THRESHOLD = 2e-38; // The non-negative minimum value of float type is 1.17549e-038.
34	
35	template <> Status CreateOperation(const infer::CohereLayerNormParam &opParam, Operation **operation)
36	{
37	    if (operation == nullptr) {
38	        return ERROR_INVALID_PARAM;
39	    }
40	    OP_PARAM_RSV_CHECK(opParam);
41	    if (!GetSingleton<Config>().Is910B()) {
42	        ATB_LOG(ERROR) << "only support Atlas 800I A2/A3 Processors";
43	        return ERROR_INVALID_PARAM;
44	    }
45	    if (opParam.epsilon < THRESHOLD) {
